import { Scene, Circle, Create } from "retiam";

class MyAnimation extends Scene {
    async run() {
        const circle = new Circle(2);
        this.add(circle);
        await this.play(new Create(circle));
    }
}

// Automatically creates a SceneComposer, binds the canvas, and starts playback:
const scene = new MyAnimation();
await scene.start(document.getElementById("canvas") as HTMLCanvasElement);

